:host { font: 14px/1.5 Pretendard, -apple-system, BlinkMacSystemFont, 'Apple SD Gothic Neo', sans-serif; color: var(--ink, #eeeaf7); }
button, input, textarea { font: inherit; }
button { cursor: pointer; transition: background 140ms var(--ease, cubic-bezier(.22, 1, .36, 1)), color 140ms var(--ease, cubic-bezier(.22, 1, .36, 1)); }
:focus-visible { outline: 2px solid var(--accent, #c3b7f5); outline-offset: 3px; }
.ds-icon { display: block; width: 16px; height: 16px; flex: 0 0 auto; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
.ds-sticky { --sticky-paper: #2e283e; --sticky-ink: #e8dff7; --sticky-muted: #bdb1d0;
      position: relative; width: 212px; background: var(--sticky-paper); color: var(--sticky-ink); border-radius: 3px;
      box-shadow: 0 12px 30px rgb(0 0 0 / 22%); transform: rotate(var(--tilt, -2deg)); pointer-events: auto; }
.ds-sticky[data-color="amber"] { --sticky-paper: #3b3225; --sticky-ink: #f1e5cc; --sticky-muted: #d0bea0; }
.ds-sticky[data-color="slate"] { --sticky-paper: #243340; --sticky-ink: #dcebf7; --sticky-muted: #aac1d3; }
.ds-sticky[data-color="rose"] { --sticky-paper: #3a2732; --sticky-ink: #f3dfe9; --sticky-muted: #d4afc0; }
.ds-sticky:focus-within { outline: 1px solid var(--sticky-muted); outline-offset: 3px; }
.ds-sticky.ds-dragging { transform: rotate(0); cursor: grabbing; }
.ds-sticky ::selection { background: var(--sticky-ink); color: var(--sticky-paper); }
.ds-sticky :focus-visible { outline-color: var(--sticky-ink); }
.ds-sticky-bar { display: flex; align-items: center; justify-content: space-between; gap: 4px; padding: 4px 5px 0 9px; }
.ds-drag-handle { display: flex; align-items: center; gap: 5px; flex: 1; min-width: 0; height: 28px; border: 0; padding: 0; background: transparent; color: var(--sticky-muted); font-size: 11px; text-align: left; cursor: grab; touch-action: none; }
.ds-drag-handle .ds-icon { width: 12px; height: 12px; }
.ds-sticky-title { display: block; width: calc(100% - 28px); margin: 7px 14px 0; padding: 0; border: 0; border-radius: 0; background: transparent; color: var(--sticky-ink); font-size: 14px; line-height: 1.6; font-weight: 580; }
.ds-sticky-title::placeholder, .ds-sticky-body::placeholder { color: var(--sticky-muted); }
.ds-sticky-body { display: block; width: 100%; min-height: 100px; max-height: 260px; border: 0; padding: 7px 14px 5px; background: transparent; color: var(--sticky-ink); font-size: 13px; line-height: 1.75; resize: vertical; overflow-wrap: anywhere; caret-color: var(--sticky-ink); }
.ds-sticky-title:focus, .ds-sticky-body:focus { outline: none; }
.ds-sticky-footer { display: flex; align-items: center; justify-content: space-between; min-height: 34px; padding: 0 9px 5px 14px; color: var(--sticky-muted); font-size: 11px; }
.ds-sticky-copy { display: inline-flex; align-items: center; justify-content: center; gap: 4px; border: 0; padding: 5px; min-height: 27px; background: transparent; color: var(--sticky-muted); font-size: 11px; border-radius: 4px; }
.ds-sticky-copy .ds-icon { width: 11px; height: 11px; }
.ds-sticky-copy:hover { color: var(--sticky-ink); background: rgb(255 255 255 / 8%); }
@media (prefers-reduced-motion: reduce) { button { transition: none !important; } }
@media (max-width:560px) { .ds-sticky-title, .ds-sticky-body { font-size:16px; } }

:host { font: 11px/1.5 Pretendard, -apple-system, BlinkMacSystemFont, 'Apple SD Gothic Neo', sans-serif; color:var(--muted, #ada6bf); }
