.ds-connection[data-state="error"] { color:var(--error, #ffb8be); }
.ds-connection button { color:inherit; text-decoration:underline; text-underline-offset:3px; padding:0; background:none; border:0; font:inherit; font-size:11px; cursor:pointer; transition:background 140ms var(--ease, cubic-bezier(.22, 1, .36, 1)), color 140ms var(--ease, cubic-bezier(.22, 1, .36, 1)); }
.ds-connection button:focus-visible { outline:2px solid var(--accent, #c3b7f5); outline-offset:3px; }
